# ///
"""Build methods.tsv, uses.tsv and computed/ from the hand-written inputs and the pins.

    uv run scripts/build.py --epoch-csv PATH [--out DIR]

Run from resources/topologies/training-methods/. Standard library only. Reads
`methods.in.tsv`, `uses.in.tsv`, `MANIFEST.tsv` and the pinned bytes in
`.cache/`; reads the Epoch AI notable-models CSV from the path given (the
anthropic-pbc repository pins it at corpus/epoch/ai-models/). Writes
`methods.tsv`, `uses.tsv` and `computed/*.tsv` under --out (default: here).
No clock, host or random value enters any output, so two runs are
byte-identical. Exits 1 if the method tree is malformed, a pin's hash does not
match, or a row marked for quotation has a quote that is not in its pin.
"""
from __future__ import annotations

import argparse
import csv
import gzip
import hashlib
import html
import json
import re
import sys
from collections import Counter, defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
CACHE = ROOT / ".cache"
WITNESS = "llm:claude-opus-5-5 prompt=unrecorded"
STAGES = ["pretraining", "mid-training", "supervised fine-tuning", "preference/RL", "distillation",
          "efficiency/compression", "safety/alignment", "evaluation", "data"]
# Hosts whose terms bar crawling, scraping or automated access: recorded, never fetched.
BARRED_HOSTS = {"www.anthropic.com": "anthropic", "anthropic.com": "anthropic",
                "www-cdn.anthropic.com": "anthropic", "assets.anthropic.com": "anthropic",
                "transformer-circuits.pub": "anthropic"}
# Heuristic for vandalised Papers with Code entries (customer-service spam overwrote real methods).
SPAM = re.compile(r"refund|cancel|customer|contact|phone|call now|helpline|airlines?|expedia|cruise|"
                  r"booking|\+1|☎|\bfaqs?\b|travel agent|subscription|how (do|can) i", re.I)
problems: list[str] = []


def read_tsv(path: Path) -> list[dict[str, str]]:
    lines = path.read_text(encoding="utf-8").splitlines()
    head = lines[0].split("\t")
    rows = []
    for n, ln in enumerate(lines[1:], 2):
        if not ln.strip():
            continue
        f = ln.split("\t")
        if len(f) != len(head):
            problems.append(f"{path.name}:{n}: {len(f)} fields, expected {len(head)}")
            f += [""] * (len(head) - len(f))
        rows.append(dict(zip(head, f)))
    return rows


def write_tsv(path: Path, cols: list[str], rows: list[dict[str, str]]) -> None:
    def clean(v: object) -> str:
        return re.sub(r"[\t\r\n]+", " ", str(v))
    out = ["\t".join(cols)] + ["\t".join(clean(r.get(c, "")) for c in cols) for r in rows]
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(out) + "\n", encoding="utf-8")


# ---------------------------------------------------------------- pins

MANIFEST = {r["id"]: r for r in read_tsv(ROOT / "MANIFEST.tsv")}
_bytes: dict[str, bytes] = {}


def pin_bytes(pin_id: str) -> bytes | None:
    if pin_id in _bytes:
        return _bytes[pin_id]
    row = MANIFEST.get(pin_id)
    if row is None:
        return None
    hits = sorted(CACHE.glob(pin_id + ".*"))
    if not hits:
        problems.append(f"pin {pin_id} in MANIFEST but missing from .cache/")
        return None
    data = hits[0].read_bytes()
    if hashlib.sha256(data).hexdigest() != row["sha256"]:
        problems.append(f"pin {pin_id}: SHA-256 does not match MANIFEST")
        return None
    _bytes[pin_id] = data
    return data


def norm(s: str) -> str:
    return re.sub(r"\s+", " ", s).strip()


def arxiv_meta(axid: str) -> dict[str, str] | None:
    raw = pin_bytes("ax-" + axid)
    if raw is None:
        return None
    t = raw.decode("utf-8", "replace")
    meta = {}
    for k in ("title", "date", "arxiv_id", "abstract"):
        m = re.search(r'<meta name="citation_%s" content="([^"]*)"' % k, t)
        meta[k] = norm(html.unescape(m.group(1))) if m else ""
    return meta if meta["arxiv_id"] == axid else None


def openalex_refs() -> dict[str, dict]:
    out: dict[str, dict] = {}
    for pid in sorted(k for k in MANIFEST if k.startswith("oa-refs-")):
        raw = pin_bytes(pid)
        if raw is None:
            continue
        for w in json.loads(raw)["results"]:
            ids = {(w.get("doi") or "").lower().replace("https://doi.org/", "")}
            for v in (w.get("ids") or {}).values():
                if isinstance(v, str) and "doi.org/" in v:
                    ids.add(v.lower().split("doi.org/", 1)[1])
            for d in ids:
                if d:
                    out[d] = w
    return out


def page_text(pin_id: str) -> str:
    """Whitespace-collapsed visible text of an HTML pin (same rules as topo.py extract)."""
    raw = pin_bytes(pin_id)
    if raw is None:
        return ""
    t = raw.decode("utf-8", "replace")
    t = re.sub(r"(?is)<(script|style|noscript|svg|template|head)\b.*?</\1>", " ", t)
    return norm(html.unescape(re.sub(r"<[^>]+>", " ", t)))


def wiki_qid(pin_id: str) -> tuple[str, str]:
    raw = pin_bytes(pin_id)
    if raw is None:
        return "", "not pinned"
    t = raw.decode("utf-8", "replace")
    q = re.search(r'"wgWikibaseItemId":"(Q\d+)"', t)
    title = re.search(r'"wgPageName":"([^"]+)"', t)
    redirected = re.search(r'"wgRedirectedFrom":"([^"]+)"', t)
    if redirected:
        return "", f"redirects to {title.group(1) if title else '?'}; QID not taken"
    return (q.group(1) if q else ""), ""


# ---------------------------------------------------------------- methods

def build_methods(pwc: dict[str, dict]) -> list[dict[str, str]]:
    rows = read_tsv(ROOT / "methods.in.tsv")
    ids = {r["id"] for r in rows}
    oa = openalex_refs()
    for r in rows:
        if r["stage"] not in STAGES:
            problems.append(f"method {r['id']}: unknown stage {r['stage']!r}")
        if r["parent_id"] and r["parent_id"] not in ids:
            problems.append(f"method {r['id']}: parent {r['parent_id']} missing")
    parent = {r["id"]: r["parent_id"] for r in rows}
    for r in rows:  # cycle check
        seen, cur = set(), r["id"]
        while cur:
            if cur in seen:
                problems.append(f"method {r['id']}: cycle in parent chain")
                break
            seen.add(cur)
            cur = parent.get(cur, "")
    out = []
    for r in rows:
        ref, title, date, status = r["first_ref"], "", "", ""
        doi = ""
        if ref.startswith("arXiv:"):
            m = arxiv_meta(ref[6:])
            doi = "10.48550/arxiv." + ref[6:]
            if m:
                title, date, status = m["title"], m["date"].replace("/", "-"), "verified:arxiv-abs"
            else:
                status = "unverified:arxiv-abs-not-pinned"
        elif ref.startswith("doi:"):
            doi = ref[4:].lower()
            status = "unverified:doi-not-found"
        elif ref.startswith("http"):
            host = re.sub(r"^https?://([^/]+).*", r"\1", ref)
            status = ("unverified:terms-barred-not-fetched" if host in BARRED_HOSTS
                      else "unverified:not-fetched")
        w = oa.get(doi.lower()) if doi else None
        topic = ""
        if w:
            if ref.startswith("doi:"):
                title, date, status = norm(w.get("title") or ""), str(w.get("publication_year") or ""), "verified:openalex"
            pt = w.get("primary_topic") or {}
            topic = (pt.get("id") or "").replace("https://openalex.org/", "")
        qid, qnote = wiki_qid(r["wikipedia_pin"]) if r["wikipedia_pin"] else ("", "")
        pwc_name, pwc_papers, pwc_note = "", "", ""
        if r["pwc_id"]:
            p = pwc.get(r["pwc_id"])
            if p is None:
                pwc_note = "pwc id not in dump"
            else:
                pwc_name, pwc_papers = p["full_name"] or "", str(p["num_papers"])
                if SPAM.search(pwc_name):
                    pwc_note = "pwc entry name vandalised in 2025-07-28 dump"
        notes = "; ".join(x for x in (qnote, pwc_note) if x)
        out.append({
            "id": r["id"], "name": r["name"], "stage": r["stage"], "parent_id": r["parent_id"],
            "definition": r["definition"], "first_ref": ref, "ref_kind": r["ref_kind"],
            "ref_title": title, "ref_date": date, "ref_status": status,
            "pwc_id": r["pwc_id"], "pwc_num_papers": pwc_papers, "wikidata_qid": qid,
            "openalex_topic_id": topic, "witness": WITNESS, "notes": notes,
        })
    return out


METHOD_COLS = ["id", "name", "stage", "parent_id", "definition", "first_ref", "ref_kind", "ref_title",
               "ref_date", "ref_status", "pwc_id", "pwc_num_papers", "wikidata_qid", "openalex_topic_id",
               "witness", "notes"]


# ---------------------------------------------------------------- uses

def build_uses(method_ids: set[str]) -> list[dict[str, str]]:
    rows = read_tsv(ROOT / "uses.in.tsv")
    out = []
    for r in rows:
        if r["method_id"] not in method_ids:
            problems.append(f"uses: unknown method {r['method_id']}")
        url, pin, quote = r["evidence_url"], r["evidence_pin"], r["quote"]
        host = re.sub(r"^https?://([^/]+).*", r"\1", url)
        if len(quote) > 200:
            problems.append(f"uses {r['developer']}/{r['method_id']}: quote over 200 chars")
        if host in BARRED_HOSTS:
            status = "unverified:terms-barred-not-fetched"
            if pin:
                problems.append(f"uses {r['developer']}/{r['method_id']}: barred host has a pin")
        elif not pin or pin not in MANIFEST:
            status = "unverified:source-not-pinned"
        elif not quote:
            status = "source-pinned:no-quote"
        else:
            if pin.startswith("ax-"):
                m = arxiv_meta(pin[3:])
                hay = m["abstract"] if m else ""
            else:
                hay = page_text(pin)
            if norm(quote) in hay:
                status = "verified:quote-in-pin"
            else:
                status = "unverified:quote-not-found"
                problems.append(f"uses {r['developer']}/{r['method_id']}: quote not in {pin}")
        out.append({**r, "status": status, "witness": WITNESS})
    return out


USE_COLS = ["developer", "country", "model", "method_id", "evidence_url", "evidence_pin", "quote",
            "status", "witness", "note"]


# ---------------------------------------------------------------- computed

def pwc_profile(dump: list[dict]) -> list[dict[str, str]]:
    years = Counter(m["introduced_year"] for m in dump)
    areas = Counter((m["collections"][0]["area"] if m["collections"] else "(none)") for m in dump)
    spam = sum(1 for m in dump if SPAM.search(m["full_name"] or "") or SPAM.search(m["name"] or ""))
    rows = [{"metric": "entries", "value": str(len(dump))},
            {"metric": "introduced_year=2000 (placeholder)", "value": str(years.get(2000, 0))},
            {"metric": "introduced_year other values", "value": str(len(dump) - years.get(2000, 0))},
            {"metric": "name matches spam heuristic", "value": str(spam)},
            {"metric": "num_papers sum", "value": str(sum(m["num_papers"] or 0 for m in dump))}]
    rows += [{"metric": f"first collection area={a}", "value": str(n)} for a, n in sorted(areas.items())]
    return rows


def openalex_years() -> list[dict[str, str]]:
    rows = []
    for pid in sorted(k for k in MANIFEST if k.startswith("oa-y-")):
        raw = pin_bytes(pid)
        if raw is None:
            continue
        d = json.loads(raw)
        phrase = re.search(r'search:%22(.*?)%22', MANIFEST[pid]["url"])
        ph = phrase.group(1).replace("%20", " ") if phrase else ""
        for g in sorted(d.get("group_by", []), key=lambda g: str(g["key"])):
            rows.append({"method_id": pid[5:], "phrase": ph, "year": str(g["key"]), "works": str(g["count"])})
    return rows


def openalex_countries() -> list[dict[str, str]]:
    rows = []
    for pid in sorted(k for k in MANIFEST if k.startswith("oa-c-")):
        raw = pin_bytes(pid)
        if raw is None:
            continue
        d = json.loads(raw)
        total = d["meta"]["count"]
        for g in sorted(d.get("group_by", []), key=lambda g: (-g["count"], str(g["key"]))):
            key = str(g["key"]).replace("https://openalex.org/countries/", "")
            rows.append({"method_id": pid[5:], "country": key, "works": str(g["count"]),
                         "works_total": str(total)})
    return rows


def period(date: str) -> str:
    y = date[:4]
    if not y.isdigit():
        return "unknown"
    y = int(y)
    return "<=2019" if y <= 2019 else "2020-2021" if y <= 2021 else "2022-2023" if y <= 2023 else str(y)


def epoch_openness(path: Path) -> list[dict[str, str]]:
    rows = list(csv.DictReader(path.open(encoding="utf-8", newline="")))
    agg: Counter = Counter()
    for r in rows:
        if "Language" not in r["Domain"]:
            continue
        country = r["Country (of organization)"].strip() or "(blank)"
        code = r["Training code accessibility"].strip() or "(blank)"
        weights = r["Model accessibility"].strip() or "(blank)"
        derived = "derived (base model named)" if r["Base model"].strip() else "no base model named"
        agg[(period(r["Publication date"]), country, weights, code, derived)] += 1
    return [{"period": k[0], "country": k[1], "model_accessibility": k[2],
             "training_code_accessibility": k[3], "lineage": k[4], "models": str(n)}
            for k, n in sorted(agg.items())]


def uses_matrix(uses: list[dict[str, str]], methods: list[dict[str, str]]) -> list[dict[str, str]]:
    stage = {m["id"]: m["stage"] for m in methods}
    agg: Counter = Counter()
    for u in uses:
        agg[(u["developer"], u["country"], stage.get(u["method_id"], "?"), u["status"].split(":")[0])] += 1
    return [{"developer": k[0], "country": k[1], "stage": k[2], "evidence": k[3], "rows": str(n)}
            for k, n in sorted(agg.items())]


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--epoch-csv", required=True, type=Path)
    ap.add_argument("--out", type=Path, default=ROOT)
    a = ap.parse_args()
    raw = pin_bytes("pwc-methods")
    dump = json.loads(gzip.decompress(raw)) if raw else []
    pwc = {m["url"].rsplit("/method/", 1)[-1]: m for m in dump}
    methods = build_methods(pwc)
    uses = build_uses({m["id"] for m in methods})
    write_tsv(a.out / "methods.tsv", METHOD_COLS, methods)
    write_tsv(a.out / "uses.tsv", USE_COLS, uses)
    c = a.out / "computed"
    write_tsv(c / "pwc-dump-profile.tsv", ["metric", "value"], pwc_profile(dump))
    write_tsv(c / "openalex-works-by-year.tsv", ["method_id", "phrase", "year", "works"], openalex_years())
    write_tsv(c / "openalex-works-by-country.tsv", ["method_id", "country", "works", "works_total"],
              openalex_countries())
    write_tsv(c / "epoch-language-model-openness.tsv",
              ["period", "country", "model_accessibility", "training_code_accessibility", "lineage", "models"],
              epoch_openness(a.epoch_csv))
    write_tsv(c / "uses-by-developer-stage.tsv", ["developer", "country", "stage", "evidence", "rows"],
              uses_matrix(uses, methods))
    epoch_sha = hashlib.sha256(a.epoch_csv.read_bytes()).hexdigest()
    write_tsv(c / "inputs.tsv", ["input", "sha256"],
              [{"input": "epoch:notable_ai_models.csv", "sha256": epoch_sha}]
              + [{"input": f, "sha256": hashlib.sha256((ROOT / f).read_bytes()).hexdigest()}
                 for f in ("methods.in.tsv", "uses.in.tsv", "MANIFEST.tsv")])
    for p in problems:
        print("PROBLEM", p, file=sys.stderr)
    print(f"methods {len(methods)}, uses {len(uses)}, problems {len(problems)}", file=sys.stderr)
    return 1 if problems else 0


if __name__ == "__main__":
    raise SystemExit(main())

