    for u in uses:
        agg[(u["developer"], u["country"], stage.get(u["method_id"], "?"), u["status"].split(":")[0])] += 1
    return [{"developer": k[0], "country": k[1], "stage": k[2], "evidence": k[3], "rows": str(n)}
            for k, n in sorted(agg.items())]


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--epoch-csv", required=True, type=Path)
    ap.add_argument("--out", type=Path, default=ROOT)
    a = ap.parse_args()
    raw = pin_bytes("pwc-methods")
    dump = json.loads(gzip.decompress(raw)) if raw else []
    pwc = {m["url"].rsplit("/method/", 1)[-1]: m for m in dump}
    methods = build_methods(pwc)
    uses = build_uses({m["id"] for m in methods})
    write_tsv(a.out / "methods.tsv", METHOD_COLS, methods)
    write_tsv(a.out / "uses.tsv", USE_COLS, uses)
    c = a.out / "computed"
    write_tsv(c / "pwc-dump-profile.tsv", ["metric", "value"], pwc_profile(dump))
    write_tsv(c / "openalex-works-by-year.tsv", ["method_id", "phrase", "year", "works"], openalex_years())
    write_tsv(c / "openalex-works-by-country.tsv", ["method_id", "country", "works", "works_total"],
              openalex_countries())
    write_tsv(c / "epoch-language-model-openness.tsv",
              ["period", "country", "model_accessibility", "training_code_accessibility", "lineage", "models"],
              epoch_openness(a.epoch_csv))
    write_tsv(c / "uses-by-developer-stage.tsv", ["developer", "country", "stage", "evidence", "rows"],
              uses_matrix(uses, methods))
    epoch_sha = hashlib.sha256(a.epoch_csv.read_bytes()).hexdigest()
    write_tsv(c / "inputs.tsv", ["input", "sha256"],
              [{"input": "epoch:notable_ai_models.csv", "sha256": epoch_sha}]
              + [{"input": f, "sha256": hashlib.sha256((ROOT / f).read_bytes()).hexdigest()}
                 for f in ("methods.in.tsv", "uses.in.tsv", "MANIFEST.tsv")])
    for p in problems:
        print("PROBLEM", p, file=sys.stderr)
    print(f"methods {len(methods)}, uses {len(uses)}, problems {len(problems)}", file=sys.stderr)
    return 1 if problems else 0


if __name__ == "__main__":
    raise SystemExit(main())
